package com.gymflow.inventory;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/v1/gyms/{gymId}/inventory")public class InventoryController{private final InventoryService service;public InventoryController(InventoryService s){service=s;}@PostMapping("/movements")@ResponseStatus(HttpStatus.CREATED)public StockMovementResponse move(@PathVariable UUID gymId,@Valid @RequestBody StockMovementRequest r){return service.move(gymId,r);}@GetMapping("/balances")public List<StockBalanceResponse> balances(@PathVariable UUID gymId){return service.balances(gymId);}@GetMapping("/movements")public List<StockMovementResponse> movements(@PathVariable UUID gymId){return service.movements(gymId);}}
